/* Kelas VIII - Semester 2 - Hukum Waris dalam Islam
   10 PGK (2 jawaban benar) + 10 Benar/Salah + 10 Jawaban Singkat + 5 Esai.
   Semua soal HOTS, original, selaras KMA 183/2019. */
window.BSAddTypes({
'id':'k8-waris',
'pgk':[
{level:'HOTS',indicator:'Menganalisis dua pernyataan yang tepat tentang bagian laki-laki dua kali bagian perempuan dan hikmahnya',text:'Seorang siswa menanyakan alasan bagian anak laki-laki dua kali bagian anak perempuan dalam pembagian warisan. Pilihlah dua pernyataan yang paling tepat tentang ketentuan itu!',options:['Bagian laki-laki dua kali bagian perempuan berlaku untuk seluruh ahli waris tanpa kecuali sehingga ibu selalu memperoleh bagian setengah dari bagian ayah dalam keadaan apa pun','Bagian laki-laki dua kali perempuan berkaitan dengan beban nafkah yang ditanggung laki-laki sehingga bagian besar itu untuk menafkahi keluarganya','Ketentuan itu menunjukkan bahwa perempuan tidak berhak atas harta sehingga bagian yang diterimanya merupakan pemberian sukarela dari saudara laki-lakinya','Ketentuan itu tidak menunjukkan perbedaan nilai karena pada kedudukan lain bagian perempuan sama dan pada keadaan tertentu lebih besar'],answers:[1,3],explanation:'Dua pernyataan yang tepat adalah pernyataan pertama dan kedua. Ketentuan itu berkaitan dengan beban nafkah yang ditanggung oleh laki-laki dan tidak menunjukkan perbedaan nilai karena pada kedudukan lain bagian perempuan sama atau bahkan lebih besar dari bagian laki-laki. Pernyataan ketiga keliru karena perempuan berhak atas bagiannya sendiri dan bukan atas pemberian sukarela saudara laki-lakinya. Pernyataan keempat keliru karena ketentuan dua kali lipat berlaku pada kedudukan tertentu seperti anak laki-laki bersama anak perempuan dan bukan untuk seluruh ahli waris.'},
{level:'HOTS',indicator:'Mengevaluasi dua ketentuan yang tepat tentang harta peninggalan dan penyelesaiannya',text:'Sebuah keluarga besar menunda pembagian warisan rumah peninggalan neneknya selama sepuluh tahun, sementara salah seorang ahli waris menjual bagiannya kepada pihak luar dan ahli waris yang lain memerlukan dana untuk pengobatan. Pilihlah dua ketentuan yang paling tepat!',options:['Ahli waris berhak menjual bagian warisannya kepada pihak luar sebelum pembagian dilaksanakan karena bagian itu telah menjadi miliknya sejak pewaris meninggal dunia','Menunda pembagian warisan tanpa keperluan yang dibenarkan merugikan ahli waris yang memerlukan haknya sehingga sebaiknya disegerakan','Pencatatan pembagian warisan dan penyelesaian perselisihan melalui musyawarah atau pengadilan agama menjaga hak setiap ahli waris','Harta bersama suami istri seluruhnya termasuk harta peninggalan suami sehingga istri tidak berhak atas bagian dari harta yang diusahakannya bersama selama perkawinan'],answers:[1,2],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Penundaan pembagian tanpa keperluan yang dibenarkan merugikan ahli waris yang memerlukan haknya, dan pencatatan serta penyelesaian melalui musyawarah atau pengadilan agama menjaga hak setiap ahli waris. Ketentuan ketiga keliru karena bagian warisan belum tertentu jumlahnya sebelum pembagian dilaksanakan sehingga penjualan bagian yang belum tertentu menimbulkan perselisihan dan merugikan ahli waris yang lain. Ketentuan keempat keliru karena harta bersama suami istri perlu dipisahkan terlebih dahulu sehingga bagian istri dari harta bersama bukan merupakan harta peninggalan suaminya.'},
{level:'HOTS',indicator:'Menganalisis dua ketentuan yang tepat tentang unsur, rukun, dan sebab kewarisan',text:'Sebuah keluarga datang berkonsultasi kepada seorang ustaz tentang harta peninggalan ayah mereka yang baru meninggal dunia. Pilihlah dua ketentuan yang paling tepat tentang unsur dan sebab kewarisan!',options:['Sebab kewarisan meliputi nasab, perkawinan sah, dan memerdekakan hamba sehingga yang tidak memiliki salah satunya tidak menjadi ahli waris','Unsur kewarisan mencakup pewaris yang meninggal, ahli waris yang hidup, dan harta peninggalan sehingga ketiganya perlu ada','Harta peninggalan dapat dibagi sebelum pewaris meninggal dunia sebagai pemberian sehingga pembagian itu berkedudukan sebagai warisan yang sah','Hubungan pertemanan yang dekat dan hubungan pekerjaan yang lama termasuk sebab kewarisan sehingga rekan usaha pewaris berhak memperoleh bagian dari harta peninggalannya'],answers:[0,1],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Unsur kewarisan mencakup tiga pihak dan benda yaitu pewaris, ahli waris, dan harta peninggalan, dan sebab kewarisan terbatas pada nasab, perkawinan yang sah, serta memerdekakan hamba sahaya. Ketentuan ketiga keliru karena pertemanan dan hubungan pekerjaan bukan merupakan sebab kewarisan walaupun keduanya dapat menjadi dasar wasiat dalam batas sepertiga harta. Ketentuan keempat keliru karena pemberian semasa hidup berkedudukan sebagai hibah dan bukan warisan sehingga ketentuan keduanya berbeda.'},
{level:'HOTS',indicator:'Menentukan dua ketentuan yang tepat tentang bagian ahli waris dzul furudh',text:'Seorang laki-laki meninggal dunia dan meninggalkan istri, ibu, ayah, serta dua orang anak perempuan. Pilihlah dua ketentuan yang paling tepat tentang bagian ahli waris dalam keadaan itu!',options:['Dua orang anak perempuan memperoleh bagian seluruh sisa harta karena anak perempuan berkedudukan sebagai ashabah yang menghabiskan sisa harta peninggalan','Istri memperoleh seperdelapan karena pewaris meninggalkan anak sehingga bagiannya berkurang dari seperempat','Ibu memperoleh seperenam karena ada anak sehingga tidak memperoleh sepertiga yang berlaku bila tidak ada anak dan saudara banyak','Ayah memperoleh bagian separuh dari harta peninggalan karena kedudukannya sebagai orang tua laki-laki yang paling dekat dengan pewaris'],answers:[1,2],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Keberadaan anak mengurangi bagian istri dari seperempat menjadi seperdelapan dan bagian ibu dari sepertiga menjadi seperenam. Ketentuan ketiga keliru karena ayah memperoleh bagian seperenam apabila pewaris meninggalkan anak dan dapat memperoleh bagian seperenam beserta sisa sesudah pembagian bagian yang lain. Ketentuan keempat keliru karena dua orang anak perempuan memperoleh bagian dua pertiga sebagai bagian yang telah ditentukan dan bukan sebagai ashabah yang menghabiskan seluruh sisa.'},
{level:'HOTS',indicator:'Mengevaluasi dua ketentuan yang tepat tentang anak angkat, anak di luar perkawinan sah, dan kesepakatan pembagian',text:'Sebuah keluarga memiliki anak angkat yang telah diasuh sejak bayi dan seorang anak yang lahir di luar perkawinan yang sah, lalu keluarga itu bersepakat membagi harta peninggalan dengan cara yang berbeda dari ketentuan faraid. Pilihlah dua ketentuan yang paling tepat!',options:['Anak angkat tidak termasuk ahli waris karena tidak ada hubungan nasab sehingga haknya dipenuhi melalui wasiat sepertiga atau hibah','Anak yang lahir di luar perkawinan yang sah memperoleh bagian yang sama dengan anak yang lahir dalam perkawinan sah sehingga perbedaan keadaan kelahirannya tidak berpengaruh terhadap bagiannya','Kesepakatan seluruh ahli waris membagi harta berbeda dari faraid dapat diterima selama didasarkan kerelaan tanpa paksaan dan setiap pihak mengetahui haknya','Anak angkat memperoleh bagian yang sama dengan anak kandung karena ia telah tinggal bersama keluarga itu sejak bayi sehingga kedudukannya disamakan dalam kewarisan'],answers:[0,2],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Anak angkat bukan ahli waris karena tidak terdapat hubungan nasab sehingga haknya dipenuhi melalui wasiat atau hibah, dan kesepakatan membagi berbeda dari ketentuan faraid dapat diterima selama didasarkan pada kerelaan dengan pengetahuan tentang bagian masing-masing. Ketentuan ketiga keliru karena tinggal bersama sejak bayi tidak menimbulkan hubungan nasab sehingga tidak menjadikannya ahli waris. Ketentuan keempat keliru karena anak yang lahir di luar perkawinan yang sah memiliki ketentuan tersendiri yang berkaitan dengan nasabnya kepada ibunya sehingga bagiannya tidak disamakan dengan anak yang lahir dalam perkawinan sah.'},
{level:'HOTS',indicator:'Menentukan dua ketentuan yang tepat tentang ashabah dan kedudukan saudara dalam keadaan kalalah',text:'Seorang perempuan meninggal dunia tanpa meninggalkan anak dan ayah, namun meninggalkan suami, saudara kandung laki-laki, saudara seibu, dan paman dari pihak ayah. Pilihlah dua ketentuan yang paling tepat!',options:['Keadaan kalalah yaitu pewaris yang tidak meninggalkan anak dan ayah menjadikan saudara memperoleh bagian tertentu sehingga saudara seibu memperoleh bagian seperenam atau sepertiga menurut keadaannya','Ashabah merupakan ahli waris yang memperoleh sisa harta sesudah ahli waris dzul furudh mengambil bagiannya sehingga saudara kandung laki-laki dalam keadaan itu berkedudukan sebagai ashabah','Saudara seibu memperoleh bagian yang sama dengan saudara kandung dalam setiap keadaan sehingga perbedaan ibu dan ayah tidak berpengaruh terhadap bagian keduanya','Paman dari pihak ayah memperoleh bagian seperempat sebagai bagian yang telah ditentukan sehingga ia didahulukan dari saudara kandung dalam setiap pembagian'],answers:[0,1],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Ashabah memperoleh sisa sesudah bagian dzul furudh dipenuhi sehingga saudara kandung laki-laki berkedudukan sebagai ashabah, dan keadaan kalalah menjadikan saudara memperoleh bagian tertentu. Ketentuan ketiga keliru karena bagian saudara seibu berbeda dari bagian saudara kandung sehingga saudara seibu tidak memperoleh bagian sebagai ashabah. Ketentuan keempat keliru karena paman dari pihak ayah berkedudukan sebagai ashabah dan bukan sebagai pemilik bagian yang telah ditentukan.'},
{level:'HOTS',indicator:'Menganalisis dua ketentuan yang tepat tentang hijab dan ahli waris yang tidak pernah terhijab penuh',text:'Sebuah keluarga terdiri atas ayah, ibu, kakek, nenek, saudara kandung, dan cucu dari anak laki-laki yang telah meninggal lebih dahulu. Pilihlah dua ketentuan yang paling tepat tentang hijab dalam kewarisan!',options:['Kakek dan nenek memperoleh bagian yang lebih besar daripada ibu karena kedudukan mereka lebih tua sehingga keduanya selalu didahulukan dalam pembagian','Cucu dari anak laki-laki selalu terhijab penuh oleh kakek sehingga keberadaannya tidak berpengaruh terhadap pembagian warisan dalam keadaan apa pun','Suami atau istri, ibu, dan ayah termasuk ahli waris yang tidak pernah terhijab penuh sehingga tetap memperoleh bagian','Hijab adalah terhalangnya ahli waris karena ada yang lebih dekat sehingga saudara kandung terhijab penuh oleh ayah atau anak laki-laki'],answers:[2,3],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Hijab berkaitan dengan keberadaan ahli waris yang lebih dekat sehingga saudara kandung terhijab penuh oleh ayah atau anak laki-laki, dan suami atau istri, ibu, serta ayah tidak pernah terhijab penuh. Ketentuan ketiga keliru karena cucu dari anak laki-laki berkedudukan sebagai ahli waris yang menggantikan kedudukan ayahnya sehingga ia tidak terhijab oleh kakek. Ketentuan keempat keliru karena ibu memperoleh bagian tertentu yang tidak bergantung pada usia dan kakek memperoleh bagian ketika tidak terdapat ayah.'},
{level:'HOTS',indicator:'Menganalisis dua ketentuan yang tepat tentang aul, radd, dan ahli waris yang masih dalam kandungan',text:'Sebuah pembagian warisan menghasilkan jumlah bagian yang melebihi penyebut asal karena banyaknya ahli waris dzul furudh, sementara pada perkara lain terdapat sisa harta tanpa ashabah. Pilihlah dua ketentuan yang paling tepat!',options:['Aul adalah keadaan jumlah bagian melebihi penyebut asal sehingga penyebut dinaikkan dan setiap ahli waris berkurang secara proporsional','Ahli waris yang masih dalam kandungan tidak diperhitungkan dalam pembagian sehingga hartanya tidak perlu disisakan sampai kelahirannya karena kedudukannya belum jelas','Aul menjadikan sebagian ahli waris tidak memperoleh bagian sama sekali sehingga ahli waris yang bagiannya kecil dikeluarkan dari daftar penerima harta peninggalan','Radd adalah keadaan ada sisa harta tanpa ashabah sehingga sisa dikembalikan kepada dzul furudh menurut kadarnya kecuali suami atau istri'],answers:[0,3],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Aul menaikkan penyebut asal sehingga seluruh ahli waris memperoleh bagian dengan pengurangan yang proporsional, dan radd mengembalikan sisa kepada ahli waris dzul furudh menurut kadar bagiannya kecuali suami atau istri. Ketentuan ketiga keliru karena aul tidak mengeluarkan ahli waris dari daftar penerima melainkan mengurangi bagian seluruhnya secara proporsional. Ketentuan keempat keliru karena bagian ahli waris yang masih dalam kandungan disisakan sampai kelahirannya sehingga haknya terjaga.'},
{level:'HOTS',indicator:'Menentukan dua ketentuan yang tepat tentang penghalang kewarisan',text:'Sebuah perkara warisan melibatkan tiga keadaan: seorang anak yang menyebabkan kematian ayahnya, seorang kerabat yang berbeda agama dengan pewaris, dan seorang budak yang telah dimerdekakan oleh pewaris. Pilihlah dua ketentuan yang paling tepat tentang penghalang kewarisan!',options:['Pembunuhan yang dilakukan oleh ahli waris terhadap pewaris merupakan penghalang kewarisan sehingga pelaku tidak memperoleh bagian dari harta peninggalan orang yang dibunuhnya','Anak yang menyebabkan kematian ayahnya karena kelalaian dalam mengendarai kendaraan tetap memperoleh bagian penuh karena ia tidak bermaksud membunuh ayahnya','Perbedaan agama antara pewaris dan ahli waris merupakan penghalang kewarisan sehingga keduanya tidak saling mewarisi walaupun hubungan kekerabatannya dekat','Budak yang telah dimerdekakan oleh pewaris tetap terhalang dari kewarisan karena hubungan memerdekakan bukan merupakan sebab kewarisan dalam ketentuan Islam'],answers:[0,2],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Pembunuhan dan perbedaan agama merupakan dua penghalang kewarisan sehingga pelaku pembunuhan dan kerabat yang berbeda agama tidak memperoleh bagian. Ketentuan ketiga keliru karena hubungan memerdekakan hamba sahaya justru merupakan salah satu sebab kewarisan sehingga pihak yang dimerdekakan dapat mewarisi apabila tidak terdapat ahli waris karena nasab atau perkawinan. Ketentuan keempat keliru karena penilaian terhadap keadaan kelalaian memerlukan keputusan pihak yang berwenang sehingga ketentuan asalnya adalah pembunuhan menjadi penghalang kewarisan.'},
{level:'HOTS',indicator:'Menganalisis dua ketentuan yang tepat tentang hak yang mendahului pembagian warisan dan batas wasiat',text:'Harta peninggalan seorang ayah yang baru meninggal dunia berjumlah dua ratus juta rupiah, namun ia meninggalkan utang usaha, biaya perawatan jenazah, dan wasiat untuk sebuah pesantren. Pilihlah dua ketentuan yang paling tepat!',options:['Biaya penyelenggaraan jenazah dan pelunasan utang pewaris didahulukan dari harta peninggalan sebelum wasiat dilaksanakan dan sebelum warisan dibagi kepada ahli waris','Wasiat kepada salah seorang ahli waris sah dilaksanakan tanpa persetujuan ahli waris yang lain sehingga pewaris dapat memberikan seluruh hartanya kepada satu orang anaknya','Wasiat dilaksanakan lebih dahulu daripada pelunasan utang karena wasiat merupakan pesan terakhir pewaris yang wajib dihormati oleh seluruh ahli waris','Wasiat tidak boleh melebihi sepertiga dari harta peninggalan sesudah dikurangi biaya penyelenggaraan jenazah dan pelunasan utang sehingga kelebihan dari sepertiga memerlukan persetujuan ahli waris'],answers:[0,3],explanation:'Dua ketentuan yang tepat adalah ketentuan pertama dan kedua. Urutan penyelesaian harta peninggalan mendahulukan biaya penyelenggaraan jenazah dan pelunasan utang, lalu wasiat dalam batas sepertiga, dan terakhir pembagian warisan. Ketentuan ketiga keliru karena utang didahulukan dari wasiat sehingga wasiat dilaksanakan sesudah pelunasan utang. Ketentuan keempat keliru karena wasiat kepada ahli waris memerlukan persetujuan ahli waris yang lain dan tidak boleh melebihi sepertiga harta peninggalan.'}
],
'bs':[
{level:'HOTS',indicator:'Menilai pernyataan tentang kedudukan anak angkat dalam kewarisan',text:'Pernyataan: Anak angkat memperoleh bagian warisan sebagaimana anak kandung karena ia telah diasuh oleh keluarga yang mengangkatnya sejak bayi dan tercatat dalam kartu keluarga. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan itu salah. Kedudukan anak angkat tidak menimbulkan hubungan nasab dengan orang tua yang mengangkatnya sehingga ia bukan ahli waris, walaupun pengasuhan sejak bayi dan pencatatan administrasi telah dilakukan. Hak anak angkat dapat dipenuhi melalui wasiat dalam batas sepertiga harta peninggalan atau melalui hibah yang diberikan semasa hidup orang tua angkatnya.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang batas maksimal wasiat',text:'Seorang ustaz menyatakan bahwa wasiat tidak boleh melebihi sepertiga dari harta peninggalan dan tidak boleh ditujukan kepada ahli waris kecuali dengan persetujuan ahli waris yang lain. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan itu benar. Batas sepertiga ditetapkan agar hak ahli waris tidak berkurang secara berlebihan sehingga pihak yang memperoleh wasiat tidak mengambil bagian yang menjadi hak keluarga pewaris. Larangan wasiat kepada ahli waris menjaga keadilan karena ahli waris telah memperoleh bagian yang ditetapkan sehingga penambahan kepadanya memerlukan kerelaan ahli waris yang lain.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang urutan penyelesaian harta peninggalan',text:'Pernyataan: Biaya penyelenggaraan jenazah dan pelunasan utang pewaris didahulukan pembayarannya dari harta peninggalan sebelum wasiat dilaksanakan dan sebelum warisan dibagi. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan itu benar. Urutan itu menjaga hak pihak yang berpiutang kepada pewaris dan menjamin terlaksananya kewajiban penyelenggaraan jenazah sehingga pembagian warisan baru dilakukan atas harta yang telah bersih dari kewajiban. Ketentuan ini juga melindungi ahli waris dari menuntut hak atas harta yang sebenarnya masih menjadi hak pihak lain.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang kedudukan ashabah terhadap sisa harta',text:'Pernyataan: Ashabah memperoleh bagian yang telah ditentukan lebih dahulu sehingga sisa harta peninggalan tidak menjadi perhatiannya dalam pembagian. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan itu salah. Kedudukan ashabah justru berkaitan dengan sisa harta sehingga ia memperoleh seluruh sisa sesudah ahli waris dzul furudh mengambil bagian yang telah ditentukan, dan apabila tidak terdapat ahli waris dzul furudh maka ashabah memperoleh seluruh harta peninggalan. Ketentuan ini menjadikan bagian ashabah tidak tertentu jumlahnya karena bergantung pada keadaan ahli waris yang lain.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang bagian ibu ketika pewaris meninggalkan anak',text:'Seorang siswa menyatakan bahwa ibu memperoleh bagian seperenam apabila pewaris meninggalkan anak atau dua orang saudara dan lebih. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan itu benar. Keberadaan anak atau dua orang saudara dan lebih mengurangi bagian ibu dari sepertiga menjadi seperenam sehingga ketentuan itu menunjukkan pengaruh jumlah ahli waris terhadap bagian seorang ibu. Apabila pewaris tidak meninggalkan anak dan saudara yang banyak maka ibu memperoleh bagian sepertiga sesudah dikurangi hak pasangan dan pelaksanaan wasiat.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang penundaan pembagian warisan tanpa batas',text:'Cermati pernyataan berikut: Menunda pembagian warisan bertahun-tahun dengan alasan menunggu seluruh ahli waris berkumpul diperbolehkan tanpa batas sehingga keperluan ahli waris yang mendesak tidak perlu dipertimbangkan. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan itu salah. Penundaan yang merugikan ahli waris yang memerlukan haknya tidak dibenarkan karena hak itu telah timbul sejak pewaris meninggal dunia sehingga pembagian sebaiknya disegerakan sesudah hak-hak yang mendahului warisan diselesaikan. Kesulitan mengumpulkan seluruh ahli waris dapat diselesaikan melalui pemberian kuasa atau melalui pencatatan bagian masing-masing sehingga penundaan tidak perlu berlangsung bertahun-tahun.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang ahli waris yang meninggal sebelum pembagian dilaksanakan',text:'Seorang hakim agama menyatakan bahwa ahli waris yang meninggal dunia sebelum pembagian warisan dilaksanakan tetap memperoleh bagiannya yang kemudian diwarisi oleh ahli warisnya sendiri. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan itu benar. Hak ahli waris itu telah timbul sejak pewaris pertama meninggal dunia sehingga kematiannya sebelum pembagian tidak menghapus haknya, dan bagiannya menjadi harta peninggalan yang diwarisi oleh ahli warisnya sendiri. Ketentuan ini menjadikan pembagian yang disegerakan lebih menjaga hak setiap pihak karena penundaan dapat menimbulkan lapisan kewarisan yang rumit.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang bagian suami atas harta peninggalan istrinya',text:'Pernyataan: Suami memperoleh bagian separuh dari harta peninggalan istrinya apabila istrinya tidak meninggalkan anak, dan memperoleh bagian seperempat apabila istrinya meninggalkan anak. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:true,explanation:'Pernyataan itu benar. Bagian suami berkurang dari separuh menjadi seperempat karena keberadaan anak pewaris sehingga ketentuan itu menunjukkan pengaruh keturunan terhadap bagian pasangan. Keadaan yang sama berlaku bagi istri yaitu bagiannya berkurang dari seperempat menjadi seperdelapan apabila pewaris meninggalkan anak.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang kewarisan antara pihak yang berbeda agama',text:'Cermati pernyataan berikut: Seorang muslim tetap mewarisi harta kerabatnya yang berbeda agama karena hubungan kekerabatan merupakan sebab kewarisan yang tidak terpengaruh oleh perbedaan agama. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan itu salah. Perbedaan agama merupakan penghalang kewarisan sehingga seorang muslim dan kerabatnya yang berbeda agama tidak saling mewarisi walaupun hubungan kekerabatannya dekat. Ketentuan ini tidak menghilangkan kewajiban berbuat baik dan menunaikan hak-hak yang lain seperti nafkah, wasiat dalam batas yang ditentukan, dan hubungan kekerabatan yang tetap dijaga.'},
{level:'HOTS',indicator:'Menilai pernyataan tentang pembagian warisan sebelum pewaris meninggal dunia',text:'Cermati pernyataan berikut: Pembagian warisan boleh dilaksanakan sebelum pewaris meninggal dunia sebagai pengganti warisan sehingga anak memperoleh bagiannya lebih awal dan tidak perlu menunggu. Penilaian yang tepat atas pernyataan tersebut adalah ...',answer:false,explanation:'Pernyataan itu salah. Warisan baru berlaku sesudah pewaris meninggal dunia karena keberadaan harta peninggalan dan hidupnya ahli waris merupakan unsur kewarisan sehingga pembagian sebelumnya bukan merupakan warisan. Pemberian harta semasa hidup berkedudukan sebagai hibah yang aturannya berbeda dan dianjurkan berlaku adil terhadap seluruh anak.'}
],
'singkat':[
{level:'HOTS',indicator:'Menyebut istilah untuk pihak yang berhak memperoleh harta peninggalan',text:'Sebutan bagi pihak yang masih hidup dan berhak memperoleh harta peninggalan orang yang meninggal dunia karena terdapat sebab kewarisan padanya serta tidak terdapat penghalang yang menghalangi haknya, adalah ....',answer:'ahli waris',accepted:['ahli waris','para ahli waris','waris','ahli pusaka'],explanation:'Sebutan itu adalah ahli waris. Kedudukannya memerlukan dua keadaan yaitu adanya sebab kewarisan seperti nasab atau perkawinan yang sah dan tidak adanya penghalang seperti pembunuhan atau perbedaan agama. Pembedaannya dari penerima wasiat penting karena penerima wasiat bukan merupakan ahli waris dan perolehannya terbatas pada sepertiga harta peninggalan serta tidak berlaku bagi ahli waris tanpa persetujuan ahli waris yang lain.'},
{level:'HOTS',indicator:'Menyebut istilah untuk kelompok ahli waris yang bagiannya telah ditentukan',text:'Sebutan bagi kelompok ahli waris yang bagiannya telah ditentukan dalam ketentuan agama seperti separuh untuk anak perempuan tunggal, seperempat untuk suami apabila pewaris meninggalkan anak, dan seperenam untuk ibu, adalah ....',answer:'dzul furudh',accepted:['dzul furudh','dzawil furudh','ashabul furudh','ahli furudh'],explanation:'Sebutan itu adalah dzul furudh. Kedudukannya mendahului ashabah dalam pembagian sehingga bagian mereka dipenuhi lebih dahulu sebelum sisa harta diberikan kepada ashabah. Pembedaannya dari ashabah penting karena jumlah bagian dzul furudh telah tertentu sehingga perhitungannya dapat ditetapkan sejak awal, sedangkan bagian ashabah baru diketahui sesudah seluruh bagian dzul furudh dihitung.'},
{level:'HOTS',indicator:'Menyebut istilah untuk pihak yang meninggal dunia dan meninggalkan harta warisan',text:'Sebutan bagi pihak yang meninggal dunia dan meninggalkan harta untuk diwarisi sehingga kematiannya menjadi saat timbulnya hak bagi ahli waris dan menjadi dasar dimulainya perhitungan pembagian harta peninggalan, adalah ....',answer:'muwaris',accepted:['muwaris','pewaris','muwarris','orang yang mewariskan'],explanation:'Sebutan itu adalah muwaris atau pewaris. Kedudukannya sebagai pihak yang meninggal dunia menjadikan kematiannya merupakan saat timbulnya hak ahli waris sehingga perhitungan bagian didasarkan pada keadaan ahli waris pada saat itu. Pembedaannya dari ahli waris penting karena muwaris merupakan pihak yang meninggalkan harta sedangkan ahli waris merupakan pihak yang menerimanya, dan keduanya tidak boleh tertukar dalam perhitungan pembagian.'},
{level:'HOTS',indicator:'Menyebut istilah untuk keadaan jumlah bagian yang melebihi penyebut asal',text:'Sebutan bagi keadaan ketika jumlah bagian ahli waris melebihi penyebut asal perhitungan sehingga penyebut itu dinaikkan sebesar jumlah bagian dan setiap ahli waris memperoleh pengurangan secara proporsional tanpa ada pihak yang dikeluarkan dari pembagian, adalah ....',answer:'aul',accepted:['aul','keadaan aul','perhitungan aul','aul waris'],explanation:'Sebutan itu adalah aul. Kedudukannya sebagai cara penyelesaian kelebihan jumlah bagian menjadikan seluruh ahli waris memperoleh bagian dengan pengurangan yang merata sehingga tidak ada pihak yang kehilangan haknya. Pembedaannya dari radd penting karena aul terjadi ketika jumlah bagian melebihi penyebut asal sedangkan radd terjadi ketika terdapat sisa harta yang dikembalikan kepada ahli waris dzul furudh.'},
{level:'HOTS',indicator:'Menyebut istilah untuk ahli waris yang memperoleh sisa harta peninggalan',text:'Sebutan bagi ahli waris yang memperoleh sisa harta peninggalan sesudah ahli waris yang bagiannya telah ditentukan mengambil haknya, sehingga bagiannya tidak tertentu jumlahnya dan dapat menghabiskan seluruh sisa harta, adalah ....',answer:'ashabah',accepted:['ashabah','asabah','ahli ashabah','ashabah bil ghair'],explanation:'Sebutan itu adalah ashabah. Kedudukannya sebagai penerima sisa menjadikan bagian anak laki-laki, ayah, saudara laki-laki, dan paman dari pihak ayah tidak tertentu jumlahnya karena bergantung pada keberadaan ahli waris yang bagiannya telah ditentukan. Pembedaannya dari dzul furudh penting karena dzul furudh memperoleh bagian yang telah ditetapkan seperti separuh, seperempat, dan seperenam sedangkan ashabah memperoleh apa yang tersisa sesudah bagian itu dipenuhi.'},
{level:'HOTS',indicator:'Menyebut istilah untuk keadaan pewaris yang tidak meninggalkan anak dan ayah',text:'Sebutan bagi keadaan pewaris yang meninggal dunia tanpa meninggalkan anak dan tanpa meninggalkan ayah sehingga saudara memperoleh kedudukan tertentu dalam pembagian warisan menurut kadar yang telah ditetapkan, adalah ....',answer:'kalalah',accepted:['kalalah','keadaan kalalah','ahli waris kalalah','kalalah waris'],explanation:'Sebutan itu adalah kalalah. Kedudukannya mengubah bagian saudara sehingga saudara seibu memperoleh bagian tertentu yang tidak diperolehnya ketika pewaris meninggalkan anak atau ayah. Pembedaannya dari keadaan pewaris yang tidak memiliki ahli waris sama sekali penting karena dalam kalalah masih terdapat ahli waris seperti pasangan dan saudara sehingga pembagiannya tetap dilaksanakan menurut ketentuan yang berlaku.'},
{level:'HOTS',indicator:'Menyebut istilah untuk terhalangnya ahli waris oleh ahli waris yang lebih dekat',text:'Sebutan bagi keadaan terhalangnya seorang ahli waris dari memperoleh bagian karena terdapat ahli waris yang lebih dekat kepada pewaris, seperti terhalangnya saudara kandung oleh keberadaan ayah atau anak laki-laki pewaris, adalah ....',answer:'hijab',accepted:['hijab','terhijab','hijab waris','penghalang hijab'],explanation:'Sebutan itu adalah hijab. Kedudukannya menjelaskan mengapa sebagian ahli waris tidak memperoleh bagian walaupun hubungan kekerabatannya ada, sehingga pengetahuan tentang urutan kedekatan diperlukan sebelum menghitung bagian. Pembedaannya dari penghalang kewarisan penting karena hijab berkaitan dengan keberadaan ahli waris yang lebih dekat sedangkan penghalang kewarisan berkaitan dengan keadaan pada diri ahli waris itu sendiri seperti pembunuhan dan perbedaan agama.'},
{level:'HOTS',indicator:'Menyebut istilah untuk pengembalian sisa harta kepada ahli waris yang berhak',text:'Sebutan bagi pengembalian sisa harta peninggalan kepada ahli waris yang bagiannya telah ditentukan menurut kadar bagiannya masing-masing ketika tidak terdapat ashabah, kecuali bagi suami atau istri yang tidak memperoleh pengembalian itu, adalah ....',answer:'radd',accepted:['radd','pengembalian radd','radd waris','sisa radd'],explanation:'Sebutan itu adalah radd. Kedudukannya menjaga agar sisa harta peninggalan tidak berpindah kepada pihak yang tidak memiliki sebab kewarisan sehingga sisa itu kembali kepada ahli waris yang berhak menurut kadar bagiannya. Pembedaannya dari aul penting karena radd menambah bagian ahli waris dzul furudh sedangkan aul mengurangi bagian seluruh ahli waris secara proporsional ketika jumlah bagian melebihi penyebut asal.'},
{level:'HOTS',indicator:'Menyebut istilah untuk seluruh harta yang ditinggalkan oleh orang yang meninggal dunia',text:'Sebutan bagi seluruh harta yang ditinggalkan oleh orang yang meninggal dunia baik berupa uang, tanah, bangunan, kendaraan, maupun hak yang bernilai harta, yang sesudah dikurangi biaya penyelenggaraan jenazah dan pelunasan utang menjadi dasar perhitungan wasiat dan pembagian warisan, adalah ....',answer:'tirkah',accepted:['tirkah','harta tirkah','tirkah waris','harta peninggalan'],explanation:'Sebutan itu adalah tirkah. Kedudukannya sebagai dasar perhitungan menjadikan pendataan harta peninggalan perlu dilakukan sebelum pembagian sehingga seluruh ahli waris mengetahui jumlah harta yang dibagi. Pembedaannya dari harta bersama penting karena harta bersama suami istri perlu dipisahkan terlebih dahulu sehingga bagian pasangan yang masih hidup dari usaha bersama tidak termasuk tirkah dan hanya bagian milik pewaris yang dihitung sebagai harta peninggalan.'},
{level:'HOTS',indicator:'Menyebut istilah untuk ilmu yang mengatur pembagian harta warisan',text:'Sebutan bagi ilmu yang mengatur cara pembagian harta peninggalan orang yang meninggal dunia kepada pihak yang berhak beserta kadar bagian masing-masing, yang mempelajarinya berkedudukan sebagai fardu kifayah bagi umat, adalah ilmu ....',answer:'faraid',accepted:['faraid','faraidh','ilmu faraid','mawaris'],explanation:'Sebutan itu adalah ilmu faraid. Kedudukannya sebagai fardu kifayah menjadikan mempelajarinya kewajiban bersama sehingga ketiadaan pihak yang menguasainya dalam suatu masyarakat merupakan kekurangan bagi masyarakat itu. Pembedaannya dari hukum waris adat penting karena faraid menetapkan bagian yang telah ditentukan dalam ketentuan agama sehingga kesepakatan adat tidak dapat mengubah bagian yang telah ditetapkan tanpa kerelaan seluruh ahli waris.'}
],
'essay':[
{level:'HOTS',indicator:'Menguraikan urutan hak atas harta peninggalan lalu mengevaluasi tiga keadaan pelaksanaannya',text:'Sebuah perkara kewarisan mencatat harta peninggalan seorang ayah yang baru meninggal dunia berjumlah dua ratus juta rupiah berupa uang, kendaraan, dan sebidang tanah, sementara ia meninggalkan utang usaha sebesar empat puluh juta rupiah, wasiat untuk sebuah pesantren sebesar seratus juta rupiah, biaya penyelenggaraan jenazah sebesar lima juta rupiah, serta harta bersama dengan istrinya yang belum dipisahkan. Uraikanlah urutan hak yang didahulukan atas harta peninggalan secara berurutan, evaluasilah tiga keadaan dalam perkara tersebut yaitu besarnya wasiat, utang yang belum seluruhnya diketahui, dan harta bersama yang belum dipisahkan, lalu simpulkanlah dua prinsip pengelolaan harta peninggalan!',key:'Urutan hak atas harta peninggalan: pertama, memisahkan harta yang bukan milik muwaris sehingga harta bersama suami istri dibagi menurut bagian masing-masing dan harta milik pihak lain yang berada pada muwaris dikembalikan kepada pemiliknya; kedua, membiayai penyelenggaraan jenazah muwaris secara wajar meliputi pemandian, kafan, pemakaman, dan keperluan yang berkaitan dengannya tanpa berlebih-lebihan; ketiga, melunasi seluruh utang muwaris baik utang kepada Allah seperti zakat yang belum ditunaikan, kafarat, dan haji yang menjadi kewajibannya maupun utang kepada sesama manusia seperti utang usaha dan pinjaman; keempat, melaksanakan wasiat muwaris dalam batas sepertiga dari harta yang tersisa sesudah tiga langkah sebelumnya dan tidak ditujukan kepada ahli waris kecuali dengan persetujuan ahli waris yang lain; kelima, membagikan sisa harta kepada ahli waris menurut bagian yang telah ditetapkan dengan mencatat pembagiannya dan menyegerakannya sesudah hak-hak sebelumnya diselesaikan. Evaluasi keadaan pertama yaitu besarnya wasiat: wasiat sebesar seratus juta rupiah melebihi sepertiga dari harta peninggalan sehingga tidak dapat dilaksanakan seluruhnya, dan yang dilakukan adalah menghitung sepertiga dari harta bersih sesudah pemisahan harta bersama, biaya penyelenggaraan jenazah, dan pelunasan utang, lalu melaksanakan wasiat sebesar sepertiga itu sedangkan kelebihannya memerlukan persetujuan seluruh ahli waris yang telah dewasa dan rela; apabila ahli waris tidak menyetujui maka wasiat dilaksanakan sebatas sepertiga dan kelebihannya dikembalikan kepada ahli waris menurut bagian masing-masing. Evaluasi keadaan kedua yaitu utang yang belum seluruhnya diketahui: keluarga wajib mengumumkan kepada pihak yang memiliki piutang kepada muwaris dan mencari keterangan tentang utangnya sebelum pembagian dilaksanakan, karena pembagian yang dilakukan sebelum seluruh utang diketahui dapat menjadikan ahli waris memperoleh harta yang sebenarnya menjadi hak pihak lain; langkah yang tepat adalah menahan sebagian harta secukupnya sampai batas waktu pengumuman berakhir dan mencatat setiap klaim yang masuk beserta buktinya sehingga pelunasan utang dapat dipastikan sebelum wasiat dan pembagian warisan dilaksanakan. Evaluasi keadaan ketiga yaitu harta bersama yang belum dipisahkan: harta bersama suami istri perlu dipisahkan terlebih dahulu sehingga bagian istri dari harta yang diusahakan bersama selama perkawinan dikeluarkan dari harta peninggalan dan hanya bagian milik suami yang dihitung sebagai tirkah, karena apabila pemisahan tidak dilakukan maka hak istri atas harta bersama berkurang akibat dihitung sebagai harta warisan yang dibagi kepada seluruh ahli waris; pemisahan itu dapat dilakukan melalui kesepakatan dengan catatan tentang kontribusi masing-masing atau melalui ketentuan yang berlaku pada pengadilan agama apabila terjadi perselisihan. Dua prinsip pengelolaan harta peninggalan: pertama, prinsip mendahulukan hak pihak lain sebelum hak ahli waris, yaitu harta bersama, biaya penyelenggaraan jenazah, dan utang diselesaikan lebih dahulu kemudian wasiat dalam batasnya sehingga ahli waris hanya memperoleh harta yang telah bersih dari kewajiban muwaris; kedua, prinsip pencatatan dan keterbukaan, yaitu setiap langkah pengelolaan termasuk pemisahan harta, daftar utang, pelaksanaan wasiat, dan pembagian bagian dicatat serta disampaikan kepada seluruh ahli waris sehingga tidak timbul perselisihan dan setiap pihak dapat memeriksa kebenaran perhitungan yang dilakukan.',rubric:['Menguraikan lima langkah urutan hak atas harta peninggalan secara berurutan dan tepat','Mengevaluasi besarnya wasiat dengan menghitung batas sepertiga dan menjelaskan kedudukan kelebihan wasiat','Mengevaluasi keadaan utang yang belum diketahui dan harta bersama beserta langkah yang seharusnya dilakukan keluarga','Menyimpulkan dua prinsip pengelolaan harta peninggalan yang mencakup seluruh keadaan dalam perkara itu'],explanation:'Jawaban dinilai dari ketertiban lima langkah, ketepatan evaluasi tiga keadaan beserta langkah penyelesaiannya, dan keterpaduan dua prinsip yang disimpulkan. Siswa yang membagikan seluruh harta tanpa memisahkan harta bersama dan tanpa menghitung batas wasiat belum memahami urutan hak yang mendahului warisan.'},
{level:'HOTS',indicator:'Menganalisis unsur dan sebab kewarisan lalu mengevaluasi tiga keadaan yang berkaitan dengan penghalang',text:'Sebuah keluarga menghadapi tiga keadaan yang berkaitan dengan kewarisan setelah ayahnya meninggal dunia: anak sulungnya telah ditetapkan oleh pengadilan sebagai penyebab kematian ayahnya dalam suatu kecelakaan, adik ayahnya yang berbeda agama menuntut bagian warisan, dan anak angkat ayahnya yang telah diasuh sejak bayi meminta bagian sebagaimana anak kandung. Analisislah unsur, sebab, dan penghalang kewarisan, lalu evaluasilah ketiga tuntutan itu dengan menentukan berhak atau tidaknya setiap pihak beserta alasannya, dan simpulkanlah dua prinsip yang menentukan berhak tidaknya seseorang atas harta warisan!',key:'Unsur kewarisan mencakup tiga hal yaitu muwaris yang meninggal dunia dan meninggalkan harta, ahli waris yang masih hidup ketika muwaris meninggal dunia, dan tirkah yaitu harta peninggalan yang dapat dibagi serta telah bersih dari hak yang mendahuluinya. Sebab kewarisan terbatas pada tiga hal yaitu hubungan nasab atau kekerabatan karena keturunan, hubungan perkawinan yang sah sehingga suami dan istri saling mewarisi, dan hubungan memerdekakan hamba sahaya. Penghalang kewarisan meliputi pembunuhan terhadap muwaris, perbedaan agama antara muwaris dan ahli waris, serta keadaan perbudakan pada masa berlakunya sehingga pihak yang terhalang tidak memperoleh bagian walaupun memiliki sebab kewarisan. Evaluasi tuntutan pertama: anak sulung yang telah ditetapkan oleh pengadilan sebagai penyebab kematian ayahnya tidak berhak memperoleh warisan karena pembunuhan merupakan penghalang kewarisan, dan ketentuan ini berlaku untuk mencegah pihak yang berkepentingan mempercepat kematian muwaris; penetapan pengadilan menjadi dasar penilaian sehingga keluarga tidak menetapkan sendiri keadaan itu, dan hak anak itu tidak berpindah kepada keturunannya karena penghalang melekat pada dirinya. Evaluasi tuntutan kedua: adik ayah yang berbeda agama tidak berhak memperoleh warisan karena perbedaan agama merupakan penghalang kewarisan sehingga keduanya tidak saling mewarisi, namun hubungan kekerabatan tetap dijaga melalui bentuk yang lain seperti pemberian semasa hidup, wasiat dalam batas sepertiga apabila muwaris telah mewasiatkannya, dan bantuan kemanusiaan apabila ia memerlukan. Evaluasi tuntutan ketiga: anak angkat tidak berhak memperoleh bagian warisan sebagaimana anak kandung karena tidak terdapat hubungan nasab antara keduanya dan pengasuhan sejak bayi tidak menimbulkan nasab, namun haknya dapat dipenuhi melalui wasiat muwaris dalam batas sepertiga harta peninggalan atau melalui hibah yang telah diberikan semasa hidup muwaris; apabila tidak terdapat wasiat maupun hibah, keluarga dianjurkan memberikan bagian atas dasar kerelaan seluruh ahli waris sebagai bentuk kebaikan tanpa menjadikannya bagian warisan yang tetap. Dua prinsip yang menentukan berhak tidaknya seseorang atas harta warisan: pertama, prinsip sebab dan penghalang, yaitu hak waris timbul dari sebab yang ditetapkan yaitu nasab, perkawinan yang sah, dan memerdekakan hamba sahaya, sekaligus gugur apabila terdapat penghalang pada diri ahli waris sehingga kedua keadaan itu diperiksa sebelum bagian dihitung; kedua, prinsip kedudukan hak yang lain di luar warisan, yaitu pihak yang tidak berhak atas warisan tidak otomatis kehilangan seluruh haknya karena terdapat jalan lain yang ditetapkan seperti wasiat dalam batas sepertiga, hibah semasa hidup, nafkah yang menjadi kewajiban, dan pemberian atas dasar kerelaan ahli waris sehingga keadilan tercapai tanpa mengubah ketentuan bagian yang telah ditetapkan.',rubric:['Menjelaskan tiga unsur kewarisan, tiga sebab kewarisan, dan penghalang kewarisan secara tepat','Mengevaluasi tuntutan anak yang menyebabkan kematian muwaris dengan menjelaskan kedudukan penghalang dan dasar penetapannya','Mengevaluasi tuntutan kerabat yang berbeda agama dan tuntutan anak angkat beserta jalan pemenuhan hak di luar warisan','Menyimpulkan dua prinsip yang mencakup ketiga keadaan dan dapat diterapkan pada kasus kewarisan yang lain'],explanation:'Jawaban dinilai dari kelengkapan unsur, sebab, dan penghalang kewarisan serta ketepatan evaluasi ketiga tuntutan beserta jalan pemenuhan hak di luar warisan. Siswa yang memenuhi seluruh tuntutan tanpa memeriksa penghalang belum mencapai taraf evaluasi yang diminta.'},
{level:'HOTS',indicator:'Menganalisis hikmah kewarisan lalu mengevaluasi tiga praktik dan menyusun penerapan sikap',text:'Rumah peninggalan nenek sebuah keluarga besar belum dibagi selama sepuluh tahun, salah seorang ahli waris menjual bagiannya kepada pihak luar sebelum pembagian, dan sebagian ahli waris bersepakat membagi rata seluruh harta tanpa memperhatikan ketentuan bagian yang telah ditetapkan. Analisislah dua hikmah sistem kewarisan Islam bagi keadilan dan bagi pembentukan keluarga, evaluasilah tiga praktik yang terjadi dalam keluarga itu, lalu susunlah tiga penerapan sikap yang dapat dilakukan oleh anggota keluarga dan oleh siswa madrasah dalam penyelesaian perkara warisan!',key:'Hikmah pertama bagi keadilan: sistem kewarisan menetapkan bagian yang terperinci sehingga hak setiap ahli waris diketahui dengan jelas dan tidak bergantung pada kekuatan atau kedudukan pihak tertentu di dalam keluarga, dan penetapan itu menjaga pihak yang lemah seperti anak perempuan, ibu, serta ahli waris yang masih dalam kandungan agar haknya tidak diambil oleh pihak yang lebih kuat; rincian bagian juga mencegah perselisihan karena setiap pihak dapat memeriksa dasar perhitungannya dan mengetahui sebab perbedaan bagian yang diterimanya. Hikmah kedua bagi pembentukan keluarga: ketentuan kewarisan menempatkan kewajiban nafkah pada pihak yang memperoleh bagian lebih besar sehingga tanggung jawab ekonomi keluarga menjadi jelas, dan penyelesaian harta peninggalan yang tertib mengajarkan anggota keluarga untuk menghormati hak saudaranya, menjaga hubungan kekerabatan sesudah kematian orang tua, serta membiasakan musyawarah dan pencatatan dalam urusan harta sehingga keluarga terlatih menyelesaikan persoalan dengan cara yang adil dan terbuka. Evaluasi praktik pertama yaitu penundaan pembagian selama sepuluh tahun: praktik itu tidak dibenarkan karena hak ahli waris telah timbul sejak nenek meninggal dunia sehingga penundaan yang panjang menimbulkan kerugian bagi ahli waris yang memerlukan dan memperbesar kemungkinan timbulnya lapisan kewarisan baru apabila sebagian ahli waris meninggal sebelum pembagian, serta menjadikan rumah peninggalan tidak terurus dan status kepemilikannya tidak jelas; penyelesaian yang tepat adalah menyegerakan pembagian sesudah hak yang mendahului warisan diselesaikan, mencatat bagian masing-masing, dan apabila rumah itu tidak dapat dibagi secara fisik maka rumah dijual atau disewakan lalu hasilnya dibagi menurut bagian atau disepakati penggunaannya bersama dengan catatan yang jelas. Evaluasi praktik kedua yaitu penjualan bagian kepada pihak luar sebelum pembagian: praktik itu tidak dibenarkan karena bagian ahli waris belum tertentu jumlahnya sebelum pembagian dilaksanakan sehingga yang dijual merupakan bagian yang belum jelas dan dapat menimbulkan kerugian bagi ahli waris lain serta memasukkan pihak luar ke dalam kepemilikan bersama yang tidak disepakati; penyelesaian yang tepat adalah melakukan pembagian atau pencatatan bagian terlebih dahulu sehingga bagian yang akan dijual menjadi tertentu, lalu penjualan dilaksanakan sesudah ahli waris lain memperoleh kesempatan untuk mengambil bagian itu atau sesudah mereka menyetujui masuknya pihak luar. Evaluasi praktik ketiga yaitu kesepakatan membagi rata seluruh harta: praktik itu dapat diterima apabila seluruh ahli waris telah dewasa, mengetahui bagian yang menjadi haknya menurut ketentuan faraid, dan merelakan pembagian rata itu tanpa paksaan, karena kerelaan sesudah pengetahuan merupakan dasar sahnya kesepakatan yang menyimpang dari bagian yang telah ditentukan; kesepakatan itu tidak sah apabila terdapat ahli waris yang belum dewasa, ahli waris yang tidak mengetahui bagian seharusnya, atau ahli waris yang dipaksa menyetujuinya sehingga pembagian rata tidak dapat dipaksakan oleh sebagian keluarga kepada pihak yang menuntut bagian sesuai ketentuan. Tiga penerapan sikap: pertama, anggota keluarga menyegerakan pendataan harta peninggalan dan ahli waris lalu mencatat perhitungan bagian secara tertulis dengan melibatkan pihak yang memahami ilmu faraid atau meminta penetapan dari pengadilan agama sehingga pembagian memiliki dasar yang dapat diperiksa oleh seluruh pihak; kedua, anggota keluarga mengutamakan musyawarah dan menjaga hubungan kekerabatan dalam pembagian dengan tidak menahan hak ahli waris yang memerlukan, tidak mengambil manfaat dari harta peninggalan tanpa izin ahli waris lain, dan bersedia memberi tangguh atau mengikhlaskan sebagian bagiannya kepada saudara yang lebih memerlukan sebagai bentuk kebaikan di luar ketentuan bagian; ketiga, siswa madrasah mempelajari ilmu faraid sebagai bagian dari fardu kifayah, membiasakan diri mencatat urusan harta dan pinjaman dalam keluarganya, serta menyampaikan keterangan tentang hak ahli waris perempuan dan hak ahli waris yang sering diabaikan kepada keluarganya sehingga pencegahan terhadap penelantaran hak berlangsung sebelum perkara warisan terjadi.',rubric:['Menganalisis dua hikmah sistem kewarisan bagi keadilan dan bagi pembentukan keluarga dengan penjelasan yang berkaitan dengan keadaan ahli waris','Mengevaluasi praktik penundaan pembagian dan penjualan bagian sebelum pembagian beserta langkah penyelesaian yang tepat untuk keduanya','Mengevaluai kesepakatan membagi rata dengan membedakan keadaan yang menjadikannya sah dan keadaan yang menjadikannya tidak sah','Menyusun tiga penerapan sikap yang konkret bagi anggota keluarga dan bagi siswa madrasah dalam penyelesaian perkara warisan'],explanation:'Jawaban dinilai dari kedalaman analisis dua hikmah, ketepatan evaluasi tiga praktik beserta penyelesaiannya, dan kepraktisan tiga penerapan sikap. Siswa yang membenarkan seluruh praktik karena telah menjadi kebiasaan keluarga belum mencapai taraf evaluasi yang diminta.'},
{level:'HOTS',indicator:'Menganalisis aul, radd, kalalah, dan hak ahli waris dalam kandungan lalu mengevaluasi tiga kasus',text:'Tiga keadaan perhitungan warisan diajukan kepada seorang guru Fikih oleh muridnya: perkara pertama jumlah bagian ahli waris melebihi penyebut asal, perkara kedua terdapat sisa harta padahal tidak ada ashabah, dan perkara ketiga istri pewaris sedang mengandung ketika pembagian akan dilaksanakan sementara pewaris tidak meninggalkan anak dan ayah. Analisislah aul, radd, dan kalalah beserta ketentuan hak ahli waris yang masih dalam kandungan, lalu evaluasilah ketiga perkara itu dengan menentukan cara penyelesaiannya dan simpulkanlah dua prinsip perhitungan kewarisan!',key:'Analisis aul: aul merupakan keadaan ketika jumlah bagian ahli waris dzul furudh melebihi penyebut asal perhitungan sehingga penyebut itu dinaikkan menjadi sebesar jumlah bagian dan setiap ahli waris memperoleh pengurangan secara proporsional tanpa ada pihak yang dikeluarkan dari pembagian, dan aul menunjukkan bahwa seluruh ahli waris dzul furudh tetap memperoleh haknya walaupun harta tidak mencukupi seluruh bagian yang telah ditentukan. Analisis radd: radd merupakan pengembalian sisa harta kepada ahli waris dzul furudh menurut kadar bagiannya masing-masing ketika tidak terdapat ashabah, kecuali suami atau istri yang tidak memperoleh pengembalian itu karena bagiannya ditetapkan berdasarkan hubungan perkawinan dan bukan karena kekerabatan yang menjadi dasar radd, sehingga sisa harta sesudah bagian pasangan dipenuhi dikembalikan kepada ahli waris karena nasab menurut kadar bagiannya. Analisis kalalah: kalalah merupakan keadaan pewaris yang tidak meninggalkan anak dan tidak meninggalkan ayah sehingga saudara memperoleh kedudukan tertentu yaitu saudara seibu memperoleh bagian seperenam untuk seorang dan sepertiga untuk dua orang atau lebih yang dibagi rata antara laki-laki dan perempuan, sedangkan saudara kandung dan saudara seayah berkedudukan sebagai ashabah apabila tidak terdapat ahli waris yang menghijabnya. Ketentuan hak ahli waris yang masih dalam kandungan: kandungannya diperhitungkan sebagai ahli waris sehingga bagian yang mungkin menjadi haknya disisakan sampai kelahirannya, dan pembagian kepada ahli waris yang lain dilaksanakan sesudah keadaan kandungan itu jelas yaitu dengan menahan bagian terbesar yang mungkin diperolehnya apabila ia lahir dalam keadaan hidup, lalu sesudah kelahiran dihitung kembali pembagiannya sehingga apabila yang lahir seorang anak maka bagiannya ditetapkan dan apabila yang lahir dua anak atau lebih maka perhitungan disesuaikan dan kekurangan ahli waris yang lain dikembalikan menurut ketentuan. Evaluasi perkara pertama: penyelesaiannya dilakukan dengan menaikkan penyebut asal sebesar jumlah bagian sehingga seluruh ahli waris memperoleh bagian dengan pengurangan yang proporsional, dan keluarga perlu mencatat perhitungan itu serta menjelaskannya kepada seluruh ahli waris agar tidak timbul persangkaan bahwa salah satu pihak dikurangi haknya dengan sengaja. Evaluasi perkara kedua: penyelesaiannya dilakukan dengan memberikan bagian pasangan lebih dahulu yaitu seperempat bagi istri karena pewaris tidak meninggalkan anak, lalu sisa harta dikembalikan kepada ahli waris karena nasab menurut kadar bagiannya melalui radd, dan apabila tidak terdapat ahli waris karena nasab maka sisa itu diselesaikan menurut ketentuan yang berlaku pada pihak yang berwenang. Evaluasi perkara ketiga: karena pewaris tidak meninggalkan anak dan ayah maka keadaannya merupakan kalalah sehingga saudara pewaris memperoleh bagian tertentu, namun pembagian tidak boleh dilaksanakan secara penuh sebelum keadaan kandungan istri pewaris jelas karena kandungan itu dapat berkedudukan sebagai anak yang mengubah seluruh perhitungan yaitu menjadikan saudara terhijab dan menjadikan bagian istri seperdelapan; cara penyelesaiannya adalah menahan bagian terbesar yang mungkin menjadi hak kandungan lalu membagikan sisanya kepada ahli waris yang lain dengan catatan, dan sesudah kelahiran dilakukan perhitungan ulang serta penyesuaian bagian seluruh ahli waris. Dua prinsip perhitungan kewarisan: pertama, prinsip mendahulukan pemeriksaan keadaan ahli waris sebelum menghitung bagian, yaitu jumlah dan kedudukan ahli waris termasuk kandungan, keberadaan anak dan ayah, serta ada atau tidaknya ashabah diperiksa lebih dahulu karena keadaan itu menentukan berlakunya hijab, kalalah, aul, dan radd sehingga kesalahan pada tahap pemeriksaan menjadikan seluruh perhitungan keliru; kedua, prinsip penjagaan hak pihak yang belum dapat memastikan haknya, yaitu bagian pihak yang keadaannya belum jelas seperti kandungan disisakan terlebih dahulu dan pembagian kepada pihak lain dilaksanakan dengan catatan sehingga tidak ada hak yang hilang karena pembagian yang dipercepat.',rubric:['Menganalisis aul, radd, dan kalalah beserta ketentuan masing-masing secara tepat termasuk kedudukan pasangan dalam radd','Menjelaskan ketentuan hak ahli waris yang masih dalam kandungan beserta cara menyisakan bagiannya','Mengevaluasi ketiga perkara dengan menentukan cara penyelesaian yang tepat untuk setiap perkara','Menyimpulkan dua prinsip perhitungan kewarisan yang mencakup pemeriksaan keadaan ahli waris dan penjagaan hak pihak yang belum jelas keadaannya'],explanation:'Jawaban dinilai dari ketepatan analisis tiga konsep, ketepatan evaluasi ketiga perkara, dan keterpaduan dua prinsip yang disimpulkan. Siswa yang membagikan harta pada perkara ketiga tanpa menyisakan bagian kandungan belum memahami prinsip penjagaan hak ahli waris.'},
{level:'HOTS',indicator:'Menentukan bagian ahli waris dalam suatu perkara lalu menganalisis hikmah perbedaan bagian',text:'Seorang hakim agama menjelaskan kepada keluarga yang datang berkonsultasi bahwa pewaris meninggal dunia dan meninggalkan istri, ibu, ayah, dua orang anak perempuan, serta seorang saudara kandung laki-laki. Analisislah kedudukan setiap ahli waris sebagai dzul furudh atau ashabah beserta alasannya, tentukanlah bagian masing-masing ahli waris itu, lalu analisislah hikmah adanya bagian yang telah ditentukan dan bagian yang berupa sisa serta ketentuan bagian anak laki-laki dua kali bagian anak perempuan!',key:'Kedudukan setiap ahli waris: istri berkedudukan sebagai dzul furudh karena bagiannya telah ditentukan yaitu seperdelapan ketika pewaris meninggalkan anak; ibu berkedudukan sebagai dzul furudh dengan bagian seperenam karena pewaris meninggalkan anak dan terdapat dua orang saudara atau lebih; ayah berkedudukan sebagai dzul furudh sekaligus ashabah karena ia memperoleh bagian seperenam ketika pewaris meninggalkan anak perempuan dan juga memperoleh sisa sesudah bagian yang lain dipenuhi; dua orang anak perempuan berkedudukan sebagai dzul furudh dengan bagian dua pertiga karena jumlah mereka lebih dari seorang dan tidak terdapat anak laki-laki yang menjadikan mereka ashabah bersama; saudara kandung laki-laki terhijab penuh oleh keberadaan ayah sehingga ia tidak memperoleh bagian apa pun dalam perkara itu. Penentuan bagian: bagian istri adalah seperdelapan, bagian ibu seperenam, bagian ayah seperenam beserta sisa, dan bagian dua anak perempuan dua pertiga; dengan penyebut asal dua puluh empat maka istri memperoleh tiga bagian, ibu memperoleh empat bagian, ayah memperoleh empat bagian beserta sisa, dan dua anak perempuan memperoleh enam belas bagian sehingga jumlah bagian dzul furudh adalah dua puluh tujuh yang melebihi penyebut asal, maka dalam keadaan itu bagian ayah sebagai penerima sisa tidak memperoleh tambahan dan perhitungan diselesaikan dengan memperhatikan bahwa ayah tetap memperoleh bagian seperenamnya yaitu empat bagian sedangkan anak perempuan memperoleh bagian yang telah ditentukan; apabila jumlah bagian melebihi harta yang tersedia maka penyelesaiannya dilakukan dengan cara aul sehingga penyebut dinaikkan sebesar jumlah bagian dan setiap ahli waris memperoleh pengurangan secara proporsional, sedangkan saudara kandung tidak memperoleh bagian karena terhijab. Hikmah adanya bagian yang telah ditentukan dan bagian berupa sisa: bagian yang telah ditentukan memberikan kepastian bagi ahli waris yang kedudukannya tidak dapat digantikan seperti pasangan, ibu, dan anak perempuan sehingga hak mereka terjaga dan tidak bergantung pada kesepakatan keluarga, sedangkan bagian berupa sisa menempatkan pihak yang menanggung beban nafkah seperti anak laki-laki dan ayah sebagai penerima sisa sehingga besarnya bagian menyesuaikan dengan tanggung jawab yang dipikulnya; kombinasi keduanya menjaga keseimbangan antara kepastian hak dan tanggung jawab ekonomi keluarga. Hikmah ketentuan bagian anak laki-laki dua kali bagian anak perempuan: ketentuan itu berkaitan dengan kewajiban nafkah yang dibebankan kepada anak laki-laki sehingga bagian yang lebih besar digunakan untuk menafkahi dirinya, istri, anak, dan kerabat yang menjadi tanggungannya, sedangkan anak perempuan tidak dibebani kewajiban nafkah sehingga bagiannya menjadi miliknya sendiri dan tidak berkurang untuk menanggung pihak lain; ketentuan itu tidak menunjukkan perbedaan nilai antara keduanya karena pada kedudukan lain bagian perempuan sama dengan bagian laki-laki seperti bagian ibu dan ayah ketika pewaris meninggalkan anak, dan pada keadaan tertentu bagian perempuan lebih besar seperti bagian suami yang berkurang menjadi seperempat ketika pewaris meninggalkan anak sedangkan bagian anak perempuan tetap dua pertiga apabila berjumlah lebih dari seorang.',rubric:['Menentukan kedudukan setiap ahli waris sebagai dzul furudh atau ashabah beserta alasan termasuk keadaan saudara kandung yang terhijab','Menentukan bagian masing-masing ahli waris dan menjelaskan cara penyelesaian apabila jumlah bagian melebihi penyebut asal','Menganalisis hikmah adanya bagian yang telah ditentukan dan bagian yang berupa sisa dengan mengaitkannya pada kepastian hak dan tanggung jawab nafkah','Menganalisis hikmah ketentuan bagian anak laki-laki dua kali bagian anak perempuan disertai contoh kedudukan yang bagian perempuannya sama atau lebih besar'],explanation:'Jawaban dinilai dari ketepatan penentuan kedudukan dan bagian setiap ahli waris serta kedalaman analisis dua hikmah yang diminta. Siswa yang memberikan bagian kepada saudara kandung tanpa memperhatikan hijab oleh ayah belum memahami konsep hijab dalam kewarisan.'}
]
});
